SELECT COUNT(*) FROM badges as b, postHistory as ph, posts as p, users as u WHERE p.OwnerUserId = u.Id AND b.UserId = u.Id AND ph.UserId = u.Id AND b."Date">=CAST('2010-07-20 10:34:10' AS TIMESTAMP) AND ph.PostHistoryTypeId=5 AND p.ViewCount>=0 AND p.ViewCount<=2024 AND u.Reputation>=1 AND u.Reputation<=750
